begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select set_config('test.teacher', gen_random_uuid()::text, true);
select set_config('test.admin', gen_random_uuid()::text, true);
select set_config('test.super', gen_random_uuid()::text, true);
select set_config('test.institution', gen_random_uuid()::text, true);
select set_config('test.class', gen_random_uuid()::text, true);
insert into auth.users(id) values (current_setting('test.teacher')::uuid), (current_setting('test.admin')::uuid), (current_setting('test.super')::uuid);
insert into public.platform_super_admins(user_id) values (current_setting('test.super')::uuid);
insert into public.institutions(id, name) values (current_setting('test.institution')::uuid, 'Override tests');
insert into public.institution_members(institution_id, user_id, role) values (current_setting('test.institution')::uuid, current_setting('test.admin')::uuid, 'admin');
insert into public.classes(id, name, class_id, created_by, institution_id) values (current_setting('test.class')::uuid, 'Override tests', gen_random_uuid()::text, current_setting('test.teacher')::uuid, current_setting('test.institution')::uuid);
select ok(not public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Missing institution row uses default');
insert into public.setting_values(scope, scope_id, key, value, allow_child_override) values ('institution', current_setting('test.institution')::uuid, 'allowed_content_types', '["learning_content"]', false);
select ok(not public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Institution disables chatbot');
set local role authenticated;
select set_config('request.jwt.claim.sub', current_setting('test.teacher'), true);
select throws_ok($$insert into public.setting_values(scope, scope_id, key, value) values ('class', current_setting('test.class')::uuid, 'allowed_content_types', '["chatbot"]')$$, '42501', 'Administrator access required', 'Teacher cannot insert override');
select set_config('request.jwt.claim.sub', current_setting('test.admin'), true);
select lives_ok($$insert into public.setting_values(scope, scope_id, key, value) values ('class', current_setting('test.class')::uuid, 'allowed_content_types', '["chatbot"]')$$, 'Institution admin overrides locked institution setting');
select ok(public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Override enables chatbot');
select set_config('test.group', (select id::text from public.class_groups where class_id = current_setting('test.class')::uuid limit 1), true);
select set_config('test.config', '{"title":"Tutor","topic_title":"Physics","language":"en","system_prompt":"Teach {topic_title} in {language}","turn_limit":1,"max_conversations":1,"web_search":false,"image_search":false,"status":"active"}', true);
select set_config('request.jwt.claim.sub', current_setting('test.teacher'), true);
select lives_ok($$select public.save_chatbot(current_setting('test.class')::uuid, current_setting('test.group')::uuid, current_setting('test.config')::jsonb)$$, 'Teacher can create chatbot enabled by admin');
select throws_ok($$update public.setting_values set value = '[]' where scope = 'class' and scope_id = current_setting('test.class')::uuid and key = 'allowed_content_types'$$, '42501', 'Administrator access required', 'Teacher cannot update override');
select throws_ok($$delete from public.setting_values where scope = 'class' and scope_id = current_setting('test.class')::uuid and key = 'allowed_content_types'$$, '42501', 'Administrator access required', 'Teacher cannot delete override');
select set_config('request.jwt.claim.sub', current_setting('test.admin'), true);
select lives_ok($$update public.setting_values set value = '[]' where scope = 'class' and scope_id = current_setting('test.class')::uuid and key = 'allowed_content_types'$$, 'Admin can set empty override');
select ok(not public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Empty override disables chatbot');
select lives_ok($$delete from public.setting_values where scope = 'class' and scope_id = current_setting('test.class')::uuid and key = 'allowed_content_types'$$, 'Admin can clear override');
reset role;
select set_config('request.jwt.claim.sub', current_setting('test.super'), true);
update public.setting_values set value = '["chatbot"]' where scope = 'institution' and scope_id = current_setting('test.institution')::uuid and key = 'allowed_content_types';
select ok(public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Cleared override inherits institution');
set local role authenticated;
select set_config('request.jwt.claim.sub', current_setting('test.super'), true);
select lives_ok($$insert into public.setting_values(scope, scope_id, key, value) values ('class', current_setting('test.class')::uuid, 'allowed_content_types', '[]')$$, 'Super admin can override');
select ok(not public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Class can narrow enabled institution types');
select lives_ok($$delete from public.setting_values where scope = 'class' and scope_id = current_setting('test.class')::uuid and key = 'allowed_content_types'$$, 'Super admin can clear override');
select lives_ok($$delete from public.setting_values where scope = 'institution' and scope_id = current_setting('test.institution')::uuid and key = 'allowed_content_types'$$, 'Super admin can remove institution row');
select lives_ok($$insert into public.setting_values(scope, scope_id, key, value) values ('class', current_setting('test.class')::uuid, 'allowed_content_types', '["chatbot"]')$$, 'Class override works without institution row');
select ok(public.chatbot_creation_allowed(current_setting('test.class')::uuid), 'Class override takes precedence over default');
select * from finish();
rollback;
